<div class="flex justify-between items-center mb-4"><p class="muted text-sm"><?= count($rows) ?> <?= strtolower($c['plural']) ?></p><a href="<?= e(url("/admin/$e/create")) ?>" class="btn btn-primary"><?= icon('plus', 'w-4 h-4') ?> Add <?= strtolower($c['singular']) ?></a></div>
<div class="card overflow-hidden"><div class="overflow-x-auto"><table class="table-x w-full text-sm"><thead><tr><?php foreach ($c['cols'] as $l): ?><th><?= e($l) ?></th><?php endforeach; ?><th></th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><?php foreach ($c['cols'] as $k => $l): ?><td><?php
 if ($k === 'image'): ?><span class="w-14 h-10 rounded-lg tint-accent overflow-hidden inline-block align-middle"><?php if ($r['image']): ?><img src="<?= e(upload_url($r['image'])) ?>" class="w-full h-full object-cover" alt=""><?php endif; ?></span>
 <?php elseif ($k === 'is_active'): ?><span class="badge <?= $r['is_active'] ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600' ?>"><?= $r['is_active'] ? 'Active' : 'Inactive' ?></span>
 <?php elseif ($k === 'schedule'): ?><span class="text-xs muted"><?= $r['starts_at'] ? e(date('d M Y H:i', strtotime($r['starts_at']))) : 'Always' ?> → <?= $r['ends_at'] ? e(date('d M Y H:i', strtotime($r['ends_at']))) : 'No end' ?></span>
 <?php else: ?><span class="<?= in_array($k, ['name', 'title']) ? 'font-semibold' : '' ?>"><?= e($r[$k] ?? '') ?></span><?php endif; ?></td><?php endforeach; ?>
<td class="whitespace-nowrap text-right"><a class="btn btn-soft btn-sm" href="<?= e(url("/admin/$e/{$r['id']}/edit")) ?>">Edit</a> <form class="inline" method="post" action="<?= e(url("/admin/$e/{$r['id']}/delete")) ?>"><?= csrf_field() ?><button class="btn btn-danger btn-sm" data-confirm="Delete this <?= strtolower($c['singular']) ?>?">Delete</button></form></td></tr>
<?php endforeach; if (!$rows): ?><tr><td colspan="<?= count($c['cols']) + 1 ?>" class="text-center muted py-12">Nothing here yet.</td></tr><?php endif; ?></tbody></table></div></div>
